// ---------------------------------------------------------------
// Interpreta el texto recibido y decide la acción sobre las tareas.
// Devuelve un objeto con "accion": crear | listar | actualizar | ayuda | error
// ---------------------------------------------------------------
const PRIORIDADES = ['alta', 'media', 'baja'];
const ESTADOS = ['pendiente', 'en_progreso', 'completada'];
const SINONIMOS_ESTADO = {
  pendiente: 'pendiente',
  progreso: 'en_progreso',
  en_progreso: 'en_progreso',
  enprogreso: 'en_progreso',
  completada: 'completada',
  completa: 'completada',
  hecha: 'completada',
  terminada: 'completada',
};

const AYUDA = [
  'Gestor de tareas - comandos:',
  '/nueva Título | prioridad | AAAA-MM-DD',
  '   prioridad opcional: alta, media o baja (por defecto media)',
  '   fecha límite opcional en formato AAAA-MM-DD',
  '/tareas - tus tareas pendientes',
  '/tareas todas - incluye las completadas',
  '/estado ID estado - pendiente, en_progreso o completada',
  '/hecha ID - marca la tarea como completada',
  '',
  'Un texto sin comando crea una tarea rápida con prioridad media.',
].join('\n');

const normalizar = (t) => String(t || '')
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .trim().toLowerCase();

function crearTarea(argumentos, base) {
  const partes = argumentos.split('|').map((p) => p.trim());
  const titulo = partes[0] || '';
  if (titulo.length < 3) {
    return { ...base, accion: 'error', respuesta: 'El título debe tener al menos 3 caracteres.\nEjemplo: /nueva Preparar presentación | alta | 2026-12-01' };
  }
  if (titulo.length > 200) {
    return { ...base, accion: 'error', respuesta: 'El título no puede superar 200 caracteres.' };
  }
  const prioridad = partes[1] ? normalizar(partes[1]) : 'media';
  if (!PRIORIDADES.includes(prioridad)) {
    return { ...base, accion: 'error', respuesta: `Prioridad no válida: "${partes[1]}". Usa alta, media o baja.` };
  }
  let fechaLimite = '';
  if (partes[2]) {
    const fecha = DateTime.fromISO(partes[2]);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(partes[2]) || !fecha.isValid) {
      return { ...base, accion: 'error', respuesta: `Fecha no válida: "${partes[2]}". Usa el formato AAAA-MM-DD, por ejemplo 2026-12-01.` };
    }
    if (fecha < $now.startOf('day')) {
      return { ...base, accion: 'error', respuesta: 'La fecha límite no puede estar en el pasado.' };
    }
    fechaLimite = fecha.toFormat('yyyy-MM-dd');
  }
  const ahora = $now.toFormat('yyyy-MM-dd HH:mm');
  return {
    ...base,
    accion: 'crear',
    id: 'T-' + Date.now().toString(36).slice(-6).toUpperCase(),
    titulo,
    prioridad,
    fecha_limite: fechaLimite,
    estado: 'pendiente',
    creada_en: ahora,
    actualizada_en: ahora,
    chat_id: base.chatId,
  };
}

function cambiarEstado(argumentos, base) {
  const [idTexto, ...resto] = argumentos.split(/\s+/).filter(Boolean);
  const id = String(idTexto || '').toUpperCase();
  if (!/^T-[A-Z0-9]{4,8}$/.test(id)) {
    return { ...base, accion: 'error', respuesta: 'Indica un ID válido, por ejemplo: /estado T-4F9K2A en_progreso\nConsulta los IDs con /tareas' };
  }
  const estado = SINONIMOS_ESTADO[normalizar(resto.join('_'))];
  if (!estado || !ESTADOS.includes(estado)) {
    return { ...base, accion: 'error', respuesta: 'Estado no válido. Usa: pendiente, en_progreso o completada.' };
  }
  return { ...base, accion: 'actualizar', id, estado };
}

function interpretarTarea(textoOriginal, chatId) {
  const base = { chatId: String(chatId || '') };
  const texto = String(textoOriginal || '').trim();
  if (!texto) {
    return { ...base, accion: 'error', respuesta: 'Solo puedo procesar mensajes de texto.\n\n' + AYUDA };
  }
  const primera = texto.split(/\s+/)[0];
  const comando = primera.startsWith('/') ? primera.toLowerCase().split('@')[0] : null;
  const argumentos = comando ? texto.slice(primera.length).trim() : texto;

  if (['/start', '/ayuda', '/help'].includes(comando)) return { ...base, accion: 'ayuda', respuesta: AYUDA };
  if (comando === null || comando === '/nueva') return crearTarea(argumentos, base);
  if (comando === '/tareas') return { ...base, accion: 'listar', incluirCompletadas: normalizar(argumentos) === 'todas' };
  if (comando === '/hecha') return cambiarEstado(`${argumentos} completada`, base);
  if (comando === '/estado') return cambiarEstado(argumentos, base);
  return { ...base, accion: 'error', respuesta: `Comando no reconocido: ${comando}\n\n${AYUDA}` };
}

// Datos del mensaje recibido por el Telegram Trigger
const mensaje = $('Telegram Trigger').first().json.message || {};
return [{ json: interpretarTarea(mensaje.text, mensaje.chat?.id) }];

// Construye el mensaje de confirmación a partir de la tarea interpretada.
const t = $('Interpretar mensaje').first().json;
const lineas = [
  'Tarea creada',
  `ID: ${t.id}`,
  `Título: ${t.titulo}`,
  `Prioridad: ${t.prioridad}`,
  `Fecha límite: ${t.fecha_limite || 'sin fecha'}`,
  '',
  `Para completarla: /hecha ${t.id}`,
];
return [{ json: { chatId: t.chatId, respuesta: lineas.join('\n') } }];

// Filtra las tareas del chat, las ordena y construye el listado.
const peticion = $('Interpretar mensaje').first().json;
const filas = $input.all().map((i) => i.json).filter((f) => f && f.id);

const propias = filas.filter((f) => String(f.chat_id) === String(peticion.chatId));
const visibles = propias.filter((f) => peticion.incluirCompletadas || f.estado !== 'completada');

const ordenPrioridad = { alta: 0, media: 1, baja: 2 };
visibles.sort((a, b) =>
  (ordenPrioridad[a.prioridad] ?? 3) - (ordenPrioridad[b.prioridad] ?? 3) ||
  String(a.fecha_limite || '9999-12-31').localeCompare(String(b.fecha_limite || '9999-12-31')));

if (visibles.length === 0) {
  return [{ json: { chatId: peticion.chatId, total: 0, respuesta: 'No tienes tareas pendientes. Crea una con /nueva Título' } }];
}

const hoy = $now.toFormat('yyyy-MM-dd');
const MAX = 25;
const lineas = visibles.slice(0, MAX).map((t) => {
  const fecha = t.fecha_limite ? ` | vence ${t.fecha_limite}${t.fecha_limite < hoy && t.estado !== 'completada' ? ' (VENCIDA)' : ''}` : '';
  return `${t.id} [${t.prioridad}] ${t.titulo} - ${t.estado}${fecha}`;
});
const titulo = peticion.incluirCompletadas ? 'Todas tus tareas' : 'Tus tareas pendientes';
let respuesta = `${titulo} (${visibles.length}):\n\n${lineas.join('\n')}`;
if (visibles.length > MAX) respuesta += `\n\n... y ${visibles.length - MAX} más.`;

return [{ json: { chatId: peticion.chatId, total: visibles.length, respuesta } }];

// Busca la tarea por ID dentro de las tareas del mismo chat.
const peticion = $('Interpretar mensaje').first().json;
const filas = $input.all().map((i) => i.json).filter((f) => f && f.id);
const tarea = filas.find((f) =>
  String(f.id).toUpperCase() === peticion.id && String(f.chat_id) === String(peticion.chatId));

if (!tarea) {
  return [{ json: {
    encontrada: false,
    chatId: peticion.chatId,
    respuesta: `No encontré la tarea ${peticion.id}. Consulta tus tareas con /tareas`,
  } }];
}

// Solo se envían a Google Sheets la columna clave (id) y las columnas que cambian.
return [{ json: {
  encontrada: true,
  id: tarea.id,
  estado: peticion.estado,
  actualizada_en: $now.toFormat('yyyy-MM-dd HH:mm'),
  chatId: peticion.chatId,
  titulo: tarea.titulo,
  estadoAnterior: tarea.estado,
} }];

// Mensaje de confirmación del cambio de estado.
const t = $('Buscar tarea').first().json;
return [{ json: {
  chatId: t.chatId,
  respuesta: `Tarea ${t.id} actualizada\n${t.titulo}\nEstado: ${t.estadoAnterior} -> ${t.estado}`,
} }];
